import sys
import time
import hashlib
from collections import deque
import os

def compute_expression(expr):
    try:
        return int(eval(expr))
    except:
        return 0

def get_cache_key(expr):
    return hashlib.sha256(expr.encode('utf-8')).digest()

def load_cache():
    if os.path.exists('expr.cache'):
        with open('expr.cache', 'rb') as f:
            return {bytes(k): int(v) for k, v in (line.split(b'\t') for line in f)}
    return {}

def save_cache(cache):
    with open('expr.cache', 'wb') as f:
        for k, v in cache.items():
            f.write(f"{k}\t{v}\n".encode('utf-8'))

def throttle_uncached():
    uncached_window = 1
    uncached_count = 0
    last_uncached_time = time.time()

    while True:
        current_time = time.time()
        if current_time - last_uncached_time >= uncached_window:
            break
        time.sleep(1 - (current_time - last_uncached_time))

        if uncached_count >= 5:
            time.sleep(1)
            current_time = time.time()
            if current_time - last_uncached_time >= uncached_window:
                break

        yield

def process_input(input_path, output_path):
    cache = load_cache()
    uncached_queue = deque()
    throttle = throttle_uncached()

    with open(input_path, 'r') as infile, open(output_path, 'w') as outfile:
        for line in infile:
            expr = line.strip()
            if not expr:
                continue

            key = get_cache_key(expr)
            if key in cache:
                outfile.write(f"{cache[key]}\n")
            else:
                uncached_queue.append(expr)
                throttle = throttle_uncached()
                for _ in uncached_queue:
                    expr = uncached_queue.popleft()
                    result = compute_expression(expr)
                    cache[key] = result
                    outfile.write(f"{result}\n")
                    save_cache(cache)
                    break

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python evalcache.py <input_path> <output_path>")
        sys.exit(1)

    process_input(sys.argv[1], sys.argv[2])

import sys
import os
import time
from hashlib import sha256
import json
import math

def truncate_fractional_part(x):
    return int(x)

def evaluate_expression(expr):
    try:
        result = eval(expr)
    except:
        return None
    return truncate_fractional_part(result)

def compute_hash(expr):
    return sha256(expr.encode('utf-8')).digest()

def load_cache():
    if os.path.exists('expr.cache'):
        with open('expr.cache', 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache):
    with open('expr.cache', 'w') as f:
        json.dump(cache, f)

def rate_limit(interval=1.0, max_operations=5):
    start_time = time.time()
    last_operations = []

    def decorator(func):
        def wrapper(*args, **kwargs):
            nonlocal start_time, last_operations
            current_time = time.time()
            if current_time - start_time >= interval:
                start_time = current_time
                last_operations = []
            last_operations.append(func(*args, **kwargs))
            if len(last_operations) > max_operations:
                time.sleep(interval - (current_time - start_time))
                start_time = current_time
                last_operations = []
        return wrapper
    return decorator

@rate_limit()
def process_expression(expr):
    cache = load_cache()
    expr_hash = compute_hash(expr)
    if expr_hash in cache:
        return cache[expr_hash]

    result = evaluate_expression(expr)
    if result is not None:
        cache[expr_hash] = result
        save_cache(cache)
    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python evalcache.py <input_path> <output_path>")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]

    with open(input_path, 'r') as infile, open(output_path, 'w') as outfile:
        for line in infile:
            expr = line.strip()
            if not expr:
                continue
            result = process_expression(expr)
            if result is not None:
                outfile.write(f"{result}\n")

if __name__ == "__main__":
    main()
